import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-Bdm5FmJO.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/02_%E8%BF%9B%E9%98%B6%E7%AF%87/01_MVCC%E4%B8%8E%E4%BA%8B%E5%8A%A1.html","title":"MVCC 与事务","lang":"zh-CN","frontmatter":{"title":"MVCC 与事务","order":1,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","MVCC","事务","隔离级别","Vacuum"]},"git":{"createdTime":1780573763000,"updatedTime":1780712648000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":8.01,"words":2404},"filePathRelative":"后端开发/数据库/PostgreSQL/02_进阶篇/01_MVCC与事务.md"}`),s={name:`01_MVCC与事务.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="mvcc-与事务" tabindex="-1"><a class="header-anchor" href="#mvcc-与事务"><span>MVCC 与事务</span></a></h1><div class="hint-container tip"><p class="hint-container-title">核心观点</p><p>PostgreSQL 的 MVCC 实现与 MySQL 完全不同——没有 Undo Log，而是<strong>在表本身存储多个版本的行（tuple）</strong>。理解 xmin/xmax 的可见性规则，是排查数据异常和 Vacuum 问题的前提。</p></div><h2 id="mvcc-基础" tabindex="-1"><a class="header-anchor" href="#mvcc-基础"><span>MVCC 基础</span></a></h2><h3 id="行版本-tuple-结构" tabindex="-1"><a class="header-anchor" href="#行版本-tuple-结构"><span>行版本（Tuple）结构</span></a></h3><p>PG 中每一行数据（tuple）都带有事务信息头：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看行的 xmin/xmax</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, xmin, xmax, cmin, cmax</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users</span></span>
<span class="line"><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 5</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span> id | name  | xmin  | xmax  | cmin | cmax</span></span>
<span class="line"><span>----+-------+-------+-------+------+-----</span></span>
<span class="line"><span>  1 | Alice | 100   | 0     | 0    | 0</span></span>
<span class="line"><span>  2 | Bob   | 101   | 0     | 0    | 0</span></span>
<span class="line"><span>  3 | Carol | 102   | 105   | 0    | 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>字段</th><th>含义</th><th>值</th></tr></thead><tbody><tr><td><strong>xmin</strong></td><td>插入该行的事务 ID</td><td>100 表示 txn 100 插入</td></tr><tr><td><strong>xmax</strong></td><td>删除/更新该行的事务 ID</td><td>0 = 仍可见；非 0 = 已被删除</td></tr><tr><td><strong>cmin</strong></td><td>插入该行的命令序号（事务内）</td><td>0 = 第一条命令</td></tr><tr><td><strong>cmax</strong></td><td>删除该行的命令序号（事务内）</td><td>0 = 未删除</td></tr></tbody></table><h3 id="可见性判断流程" tabindex="-1"><a class="header-anchor" href="#可见性判断流程"><span>可见性判断流程</span></a></h3>`,9),i(d,{code:``}),o[1]||=n(`<h3 id="完整示例" tabindex="-1"><a class="header-anchor" href="#完整示例"><span>完整示例</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 准备测试数据</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> accounts</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id      </span><span style="color:#C678DD;">integer</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;">    text</span><span style="color:#C678DD;"> NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    balance </span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> accounts (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, balance) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;Alice&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">), (</span><span style="color:#98C379;">&#39;Bob&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">500</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看 xmin/xmax</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, balance, xmin, xmax </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  id | name  | balance  | xmin | xmax</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ----+-------+----------+------+-----</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   1 | Alice |  1000.00 |  100 |   0</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   2 | Bob   |   500.00 |  100 |   0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A：更新 Alice 余额（未提交）</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> txid_current();  </span><span style="color:#7F848E;font-style:italic;">-- 假设 101</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 800</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不提交</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 另一个会话查看</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, balance, xmin, xmax </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  id | name  | balance  | xmin | xmax</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ----+-------+----------+------+-----</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   1 | Alice |  1000.00 |  100 | 101   ← 旧版本：xmax=101 表示被 txn 101 标记删除</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- （新版本 xmin=101 对我们不可见，因为 101 未提交）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 A 提交</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 再次查看</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, balance, xmin, xmax </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--  id | name  | balance | xmin | xmax</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ----+-------+---------+------+-----</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">--   1 | Alice |  800.00 |  101 |   0  ← 新版本可见</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- （旧版本 xmin=100, xmax=101 已不可见，等待 Vacuum 清理）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="事务-id-回卷-wraparound" tabindex="-1"><a class="header-anchor" href="#事务-id-回卷-wraparound"><span>事务 ID 回卷（Wraparound）</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 事务 ID 是 32 位整数，最大约 21 亿</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 超过后会回卷到 0，导致可见性判断混乱</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看当前事务 ID 和回卷风险</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> txid_current(),</span></span>
<span class="line"><span style="color:#ABB2BF;">       age(datfrozenxid) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> tx_age,</span></span>
<span class="line"><span style="color:#D19A66;">       2000000000</span><span style="color:#ABB2BF;"> - age(datfrozenxid) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> tx_until_wraparound</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_database </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> datname </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> current_database();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看每个表的冻结年龄</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname,</span></span>
<span class="line"><span style="color:#ABB2BF;">       age(relfrozenxid) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> age,</span></span>
<span class="line"><span style="color:#ABB2BF;">       pg_size_pretty(pg_total_relation_size(</span><span style="color:#C678DD;">oid</span><span style="color:#ABB2BF;">)) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> size</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_class</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> relkind </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;r&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;t&#39;</span><span style="color:#ABB2BF;">)  </span><span style="color:#7F848E;font-style:italic;">-- 普通表和 TOAST 表</span></span>
<span class="line"><span style="color:#C678DD;">  AND</span><span style="color:#ABB2BF;"> age(relfrozenxid) </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 100000000</span><span style="color:#7F848E;font-style:italic;">  -- 超过 1 亿的表需要关注</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> age </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">事务 ID 回卷是 PG 最严重的故障</p><ul><li>当 <code>age(relfrozenxid)</code> 接近 20 亿时，PG 会<strong>强制停写</strong>以防止数据损坏</li><li>此时数据库变为只读，必须执行 <code>VACUUM FREEZE</code> 恢复</li><li><strong>预防</strong>：确保 autovacuum 正常运行，监控 <code>age(relfrozenxid)</code></li><li>参考文档：<a href="https://www.postgresql.org/docs/16/routine-vacuuming.html#VACUUM-FOR-WRAPAROUND" target="_blank" rel="noopener noreferrer">Preventing Transaction ID Wraparound Failures</a></li></ul></div><h3 id="vacuum-freeze-机制" tabindex="-1"><a class="header-anchor" href="#vacuum-freeze-机制"><span>Vacuum Freeze 机制</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- Vacuum 的 freeze 操作：将旧 tuple 的 xmin 标记为 &quot;FrozenXID&quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- FrozenXID 永远可见，不再参与年龄计算</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 手动冻结（紧急恢复用）</span></span>
<span class="line"><span style="color:#ABB2BF;">VACUUM FREEZE accounts;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看冻结配置</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW vacuum_freeze_min_age;        </span><span style="color:#7F848E;font-style:italic;">-- 默认 5000 万，超过此年龄可冻结</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW vacuum_freeze_table_age;      </span><span style="color:#7F848E;font-style:italic;">-- 默认 1.5 亿，超过此年龄触发全表 freeze</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum_freeze_max_age;    </span><span style="color:#7F848E;font-style:italic;">-- 默认 2 亿，超过此年龄强制 autovacuum</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="事务隔离级别" tabindex="-1"><a class="header-anchor" href="#事务隔离级别"><span>事务隔离级别</span></a></h2>`,8),i(d,{code:``}),o[2]||=n(`<h3 id="read-committed-读已提交" tabindex="-1"><a class="header-anchor" href="#read-committed-读已提交"><span>READ COMMITTED（读已提交）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- PG 默认隔离级别</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW default_transaction_isolation;  </span><span style="color:#7F848E;font-style:italic;">-- read committed</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 特点：每条 SQL 语句获取新的快照</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 800.00</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B（同时）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 900</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A 再次查询（同一事务内）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 900.00 ← 看到了 B 的修改！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="repeatable-read-可重复读" tabindex="-1"><a class="header-anchor" href="#repeatable-read-可重复读"><span>REPEATABLE READ（可重复读）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> ISOLATION</span><span style="color:#C678DD;"> LEVEL</span><span style="color:#C678DD;"> REPEATABLE</span><span style="color:#C678DD;"> READ</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 900.00</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B（同时）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 700</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A 再次查询（同一事务内）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 900.00 ← 仍然是旧值！</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A 尝试修改（会报错）</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 600</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ERROR: could not serialize access due to concurrent update</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">PG 的 REPEATABLE READ 不会幻读</p><p>SQL 标准定义 REPEATABLE READ 允许幻读，但 PG 的实现实际上<strong>阻止了幻读</strong>：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> ISOLATION</span><span style="color:#C678DD;"> LEVEL</span><span style="color:#C678DD;"> REPEATABLE</span><span style="color:#C678DD;"> READ</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 800</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 1 行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B</span></span>
<span class="line"><span style="color:#C678DD;">INSERT INTO</span><span style="color:#ABB2BF;"> accounts (</span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, balance) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;Carol&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">900</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 800</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 仍然是 1 行，不会幻读</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>PG 的 MVCC 快照机制天然阻止了幻读。这是 PG 相对 MySQL 的一个优势。</p></div><h3 id="serializable-可串行化" tabindex="-1"><a class="header-anchor" href="#serializable-可串行化"><span>SERIALIZABLE（可串行化）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- PG 使用 SSI（Serializable Snapshot Isolation）实现</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 检测写冲突并回滚</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> ISOLATION</span><span style="color:#C678DD;"> LEVEL</span><span style="color:#C678DD;"> SERIALIZABLE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 700.00</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 B</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span><span style="color:#C678DD;"> ISOLATION</span><span style="color:#C678DD;"> LEVEL</span><span style="color:#C678DD;"> SERIALIZABLE</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> balance </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 700.00</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 600</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 会话 A</span></span>
<span class="line"><span style="color:#C678DD;">UPDATE</span><span style="color:#ABB2BF;"> accounts </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> balance </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 500</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#C678DD;"> WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;Alice&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- ERROR: could not serialize access due to concurrent update</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">COMMIT</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="与-mysql-mvcc-的对比" tabindex="-1"><a class="header-anchor" href="#与-mysql-mvcc-的对比"><span>与 MySQL MVCC 的对比</span></a></h2>`,8),i(d,{code:``}),o[3]||=n(`<table><thead><tr><th>对比项</th><th>PostgreSQL</th><th>MySQL (InnoDB)</th></tr></thead><tbody><tr><td>多版本存储</td><td>数据页中直接存多个 tuple</td><td>数据页 + Undo Log 链</td></tr><tr><td>旧版本位置</td><td>与新版本同在表数据页</td><td>Undo Log 表空间</td></tr><tr><td>回滚机制</td><td>标记 xmax，tuple 仍在</td><td>沿 Undo Log 链反向恢复</td></tr><tr><td>清理机制</td><td>Vacuum（自动/手动）</td><td>Purge 线程（自动）</td></tr><tr><td>表膨胀</td><td><strong>是</strong>，更新产生死元组</td><td>否，数据页紧凑</td></tr><tr><td>长事务影响</td><td>表膨胀 + Vacuum 延迟</td><td>Undo Log 膨胀</td></tr><tr><td>SELECT 性能</td><td>需要检查可见性</td><td>读取最新版本 + 沿 Undo Log</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">PG 的表膨胀问题</p><p>PG 的 MVCC 最大缺点是<strong>表膨胀</strong>：频繁 UPDATE/DELETE 会产生大量死元组（dead tuples），即使 Vacuum 后，数据页也可能存在空洞。</p><p>解决方案：</p><ul><li>定期 <code>VACUUM</code> 或确保 autovacuum 正常</li><li>严重膨胀时用 <code>pg_repack</code> 或 <code>VACUUM FULL</code> 重建表</li><li>监控 <code>pg_stat_user_tables.n_dead_tup</code></li></ul></div><h2 id="hot-更新优化" tabindex="-1"><a class="header-anchor" href="#hot-更新优化"><span>HOT 更新优化</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- HOT (Heap-Only Tuple) Update</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 当 UPDATE 不修改索引列时，PG 可以在同一数据页内创建新版本</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 不需要更新索引！这大幅减少 IO</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- HOT 更新条件：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 新旧 tuple 在同一个数据页</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 没有修改任何索引列</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看表的 HOT 更新比例</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname,</span></span>
<span class="line"><span style="color:#ABB2BF;">       n_tup_upd </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total_updates,</span></span>
<span class="line"><span style="color:#ABB2BF;">       n_tup_hot_upd </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> hot_updates,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(n_tup_hot_upd::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(n_tup_upd, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> hot_pct</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_user_tables</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> n_tup_upd </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span> relname | total_updates | hot_updates | hot_pct</span></span>
<span class="line"><span>---------+---------------+-------------+---------</span></span>
<span class="line"><span> orders  |       1500000 |     1200000 | 80.0%</span></span>
<span class="line"><span> users   |        500000 |      450000 | 90.0%</span></span>
<span class="line"><span> logs    |       3000000 |      600000 | 20.0%</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">提高 HOT 更新比例</p><ol><li><strong>不要更新索引列</strong>：只更新非索引列可以触发 HOT</li><li><strong>增大 fillfactor</strong>：默认 100%，降到 80-90% 留空间给 HOT 更新</li><li><strong>选择合适的索引列</strong>：避免对频繁更新的列建索引</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 设置 fillfactor（需要重建表）</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> (fillfactor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 85</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">VACUUM FULL orders;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h2 id="autovacuum-机制" tabindex="-1"><a class="header-anchor" href="#autovacuum-机制"><span>Autovacuum 机制</span></a></h2><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看 autovacuum 配置</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum;                  </span><span style="color:#7F848E;font-style:italic;">-- 默认 on</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum_naptime;          </span><span style="color:#7F848E;font-style:italic;">-- 默认 1min（每分钟检查一次）</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum_max_workers;      </span><span style="color:#7F848E;font-style:italic;">-- 默认 3 个 worker</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum_vacuum_threshold; </span><span style="color:#7F848E;font-style:italic;">-- 默认 50（50 次更新触发）</span></span>
<span class="line"><span style="color:#ABB2BF;">SHOW autovacuum_vacuum_scale_factor; </span><span style="color:#7F848E;font-style:italic;">-- 默认 0.2（20% 行变更触发）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 触发条件：dead tuples &gt; threshold + scale_factor * reltuples</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 例如：10 万行的表，dead tuples &gt; 50 + 0.2 * 100000 = 20050 时触发</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 查看各表的 autovacuum 状态</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> relname,</span></span>
<span class="line"><span style="color:#ABB2BF;">       n_dead_tup,</span></span>
<span class="line"><span style="color:#ABB2BF;">       n_live_tup,</span></span>
<span class="line"><span style="color:#ABB2BF;">       last_vacuum,</span></span>
<span class="line"><span style="color:#ABB2BF;">       last_autovacuum,</span></span>
<span class="line"><span style="color:#ABB2BF;">       last_analyze,</span></span>
<span class="line"><span style="color:#ABB2BF;">       last_autoanalyze</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_user_tables</span></span>
<span class="line"><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> n_dead_tup </span><span style="color:#C678DD;">DESC</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 为大表调整 autovacuum 阈值</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 默认 20% 对大表太保守（1 亿行的表要 2000 万 dead tuples 才触发）</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> large_logs </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_vacuum_scale_factor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">01</span><span style="color:#ABB2BF;">,   </span><span style="color:#7F848E;font-style:italic;">-- 1% 就触发</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_analyze_scale_factor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">01</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 或者直接设固定阈值</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> large_logs </span><span style="color:#C678DD;">SET</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_vacuum_threshold </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 100000</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    autovacuum_vacuum_scale_factor </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 监控 Vacuum 进度（PG 12+）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> pid,</span></span>
<span class="line"><span style="color:#ABB2BF;">       datname,</span></span>
<span class="line"><span style="color:#ABB2BF;">       relid::regclass </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> table_name,</span></span>
<span class="line"><span style="color:#ABB2BF;">       phase,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(heap_blks_scanned::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(heap_blks_total, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> scan_pct,</span></span>
<span class="line"><span style="color:#56B6C2;">       round</span><span style="color:#ABB2BF;">(heap_blks_vacuumed::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">nullif</span><span style="color:#ABB2BF;">(heap_blks_total, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> vacuum_pct</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> pg_stat_progress_vacuum;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>PG 的 MVCC 和 MySQL 有什么区别？</strong></p><ul><li>PG：多版本存在数据页（tuple），无 Undo Log</li><li>MySQL：最新版本在数据页，历史版本在 Undo Log 链</li><li>PG 的代价是表膨胀，MySQL 的代价是 Undo Log 膨胀</li></ul></li><li><p><strong>什么是事务 ID 回卷？怎么预防？</strong></p><ul><li>32 位事务 ID 耗尽后回卷，导致可见性混乱</li><li>autovacuum freeze 自动处理</li><li>监控 <code>age(relfrozenxid)</code>，确保 autovacuum 正常运行</li></ul></li><li><p><strong>PG 的 REPEATABLE READ 和 SQL 标准有什么不同？</strong></p><ul><li>SQL 标准允许幻读，PG 实际阻止了幻读</li><li>PG 的快照机制天然阻止幻读（严格来说已达到 SERIALIZABLE 效果）</li></ul></li><li><p><strong>HOT 更新是什么？</strong></p><ul><li>Heap-Only Tuple：不修改索引列时，新版本放在同一数据页</li><li>不需要更新索引，大幅减少 IO</li><li>提高 fillfactor 可以增加 HOT 更新概率</li></ul></li><li><p><strong>autovacuum 不工作怎么办？</strong></p><ul><li>检查 <code>autovacuum</code> 是否开启</li><li>大表的 scale_factor 太大，调低或设固定阈值</li><li>检查是否有长事务阻止 Vacuum（<code>pg_stat_activity</code>）</li><li>检查是否有锁冲突</li></ul></li></ol></div><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.postgresql.org/docs/16/mvcc.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - MVCC</a></li><li><a href="https://www.postgresql.org/docs/16/routine-vacuuming.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Routine Vacuuming</a></li><li><a href="https://www.postgresql.org/docs/16/transaction-iso.html" target="_blank" rel="noopener noreferrer">PostgreSQL 官方文档 - Transaction Isolation</a></li><li><a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase GitHub</a></li></ul>`,14)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};